-- ES/DE/FR translations for all 7 Australia milestones.
-- au-ncereceive, au-30pct, and au-automate reuse the tracker's own
-- phrasing per tracker-phrasing-wins.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-anz-arrangement-2018', 'es', 'Acuerdo de Facturación Electrónica Gubernamental Australia–Nueva Zelanda', 'Ambos gobiernos acuerdan un enfoque común para la facturación electrónica — la base de la especificación compartida PINT A-NZ que ambos países utilizan hoy.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-anz-arrangement-2018', 'de', 'Elektronisches Rechnungsabkommen zwischen der Regierung Australiens und Neuseelands', 'Beide Regierungen einigen sich auf einen gemeinsamen Ansatz für die elektronische Rechnungsstellung — die Grundlage für die gemeinsame Spezifikation PINT A-NZ, die beide Länder heute verwenden.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-anz-arrangement-2018', 'fr', 'Accord gouvernemental Australie–Nouvelle-Zélande sur la facturation électronique', 'Les deux gouvernements conviennent d''une approche commune de la facturation électronique — le fondement de la spécification partagée PINT A-NZ que les deux pays utilisent aujourd''hui.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-ncereceive', 'es', 'Los organismos federales deben poder recibir facturas electrónicas Peppol obligatoriamente (en vigor desde julio de 2022)', 'Todas las Entidades del Commonwealth No Corporativas (organismos federales) deben poder recibir facturas electrónicas Peppol desde el 1 de julio de 2022. No existe un mandato B2B general, pero la adopción por parte del gobierno sigue acelerándose.', '["Proveedores de organismos federales: conéctense a través de un Punto de Acceso Peppol acreditado por la ATO", "Las facturas entregadas vía Peppol pueden pagarse en 5 días en lugar de los 20 estándar"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-ncereceive', 'de', 'Bundesbehörden müssen Peppol-E-Rechnungen empfangen können (seit Juli 2022 in Kraft)', 'Alle Non-Corporate Commonwealth Entities (Bundesbehörden) müssen seit dem 1. Juli 2022 in der Lage sein, Peppol-E-Rechnungen zu empfangen. Es besteht keine allgemeine B2B-Pflicht, aber die Akzeptanz durch die Regierung beschleunigt sich weiter.', '["Lieferanten von Bundesbehörden: verbinden Sie sich über einen von der ATO akkreditierten Peppol Access Point", "Über Peppol zugestellte Rechnungen können innerhalb von 5 statt der üblichen 20 Tage bezahlt werden"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-ncereceive', 'fr', 'Les agences fédérales doivent obligatoirement pouvoir recevoir des factures électroniques Peppol (en vigueur depuis juillet 2022)', 'Toutes les Non-Corporate Commonwealth Entities (agences fédérales) doivent pouvoir recevoir des factures électroniques Peppol depuis le 1er juillet 2022. Il n''existe pas d''obligation B2B générale, mais l''adoption par le gouvernement continue de s''accélérer.', '["Fournisseurs des agences fédérales : connectez-vous via un Access Point Peppol accrédité par l''ATO", "Les factures livrées via Peppol peuvent être payées sous 5 jours au lieu des 20 jours standard"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-pint-mandatory-2024', 'es', 'PINT A-NZ se convierte en obligatorio', 'La especificación Peppol International actualizada para Australia y Nueva Zelanda sustituye a la anterior extensión A-NZ Peppol BIS Billing.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-pint-mandatory-2024', 'de', 'PINT A-NZ wird verpflichtend', 'Die aktualisierte Peppol-International-Spezifikation für Australien und Neuseeland ersetzt die frühere A-NZ-Peppol-BIS-Billing-Erweiterung.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-pint-mandatory-2024', 'fr', 'PINT A-NZ devient obligatoire', 'La spécification Peppol International mise à jour pour l''Australie et la Nouvelle-Zélande remplace l''extension A-NZ Peppol BIS Billing antérieure.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-legacy-removed-2025', 'es', 'Las especificaciones heredadas se eliminan por completo', 'Todos los usuarios deben intercambiar en PINT A-NZ — se convierte en la única especificación admitida para enviar y recibir facturas y notas de crédito en la red.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-legacy-removed-2025', 'de', 'Veraltete Spezifikationen vollständig entfernt', 'Alle Nutzer müssen PINT A-NZ verwenden — es wird zur einzigen unterstützten Spezifikation für das Senden und Empfangen von Rechnungen und Gutschriften im Netzwerk.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-legacy-removed-2025', 'fr', 'Les spécifications héritées sont entièrement supprimées', 'Tous les utilisateurs doivent échanger en PINT A-NZ — cela devient la seule spécification prise en charge pour l''envoi et la réception de factures et de notes de crédit sur le réseau.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-default-2025', 'es', 'La ATO establece la facturación electrónica como opción predeterminada para las NCE', 'La Oficina de Impuestos de Australia anuncia que la facturación electrónica se convierte en el método predeterminado de intercambio de facturas para las Entidades del Commonwealth No Corporativas, como parte de una estrategia más amplia para reducir la carga administrativa y acelerar los ciclos de pago.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-default-2025', 'de', 'ATO legt E-Rechnung als Standard für NCEs fest', 'Das australische Finanzamt kündigt an, dass die E-Rechnung zur Standardmethode für den Rechnungsaustausch für Non-Corporate Commonwealth Entities wird — Teil einer umfassenderen Strategie zur Senkung des Verwaltungsaufwands und zur Beschleunigung der Zahlungszyklen.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-default-2025', 'fr', 'L''ATO établit la facturation électronique comme méthode par défaut pour les NCE', 'L''administration fiscale australienne annonce que la facturation électronique devient la méthode d''échange de factures par défaut pour les Non-Corporate Commonwealth Entities, dans le cadre d''une stratégie plus large visant à réduire la charge administrative et à accélérer les cycles de paiement.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-30pct', 'es', 'El 30 % de las facturas de organismos federales debe procesarse a través de Peppol', 'Las Entidades del Commonwealth No Corporativas deben lograr que al menos el 30 % de las facturas de proveedores recibidas fluyan a través de la red Peppol, en el camino hacia la automatización completa para diciembre de 2026.', '["Si abastece a organismos federales australianos, confirme que su facturación está habilitada para Peppol", "Utilice el formato PINT A-NZ — el único estándar admitido desde el 15 de mayo de 2025"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-30pct', 'de', '30 % der Rechnungen von Bundesbehörden müssen über Peppol verarbeitet werden', 'Non-Corporate Commonwealth Entities müssen mindestens 30 % der eingegangenen Lieferantenrechnungen über das Peppol-Netzwerk abwickeln, auf dem Weg zur vollständigen Automatisierung bis Dezember 2026.', '["Wenn Sie australische Bundesbehörden beliefern, bestätigen Sie, dass Ihre Rechnungsstellung Peppol-fähig ist", "Verwenden Sie das PINT-A-NZ-Format — den einzigen seit dem 15. Mai 2025 unterstützten Standard"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-30pct', 'fr', '30 % des factures des agences fédérales doivent être traitées via Peppol', 'Les Non-Corporate Commonwealth Entities doivent faire transiter au moins 30 % des factures fournisseurs reçues par le réseau Peppol, en vue d''une automatisation complète d''ici décembre 2026.', '["Si vous fournissez des agences fédérales australiennes, vérifiez que votre facturation est compatible Peppol", "Utilisez le format PINT A-NZ — la seule norme prise en charge depuis le 15 mai 2025"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-automate', 'es', 'Los organismos federales deben automatizar el envío y procesamiento de facturas electrónicas', 'Las Entidades del Commonwealth No Corporativas deben poder procesar automáticamente las facturas electrónicas recibidas y enviar facturas electrónicas, con informes trimestrales de progreso a la Autoridad Peppol de Australia.', '["Confirme que su configuración de facturación electrónica admite un procesamiento totalmente automatizado y sin intervención manual", "Los proveedores del gobierno deben esperar ciclos de pago más rápidos a medida que se implanta la automatización"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-automate', 'de', 'Bundesbehörden müssen das Senden und Verarbeiten von E-Rechnungen automatisieren', 'Non-Corporate Commonwealth Entities müssen in der Lage sein, eingehende E-Rechnungen automatisch zu verarbeiten und E-Rechnungen zu versenden, mit vierteljährlicher Fortschrittsberichterstattung an die australische Peppol-Behörde.', '["Bestätigen Sie, dass Ihre E-Rechnungslösung eine vollständig automatisierte, berührungslose Verarbeitung unterstützt", "Öffentliche Lieferanten sollten mit der Einführung der Automatisierung schnellere Zahlungszyklen erwarten"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-automate', 'fr', 'Les agences fédérales doivent automatiser l''envoi et le traitement des factures électroniques', 'Les Non-Corporate Commonwealth Entities doivent pouvoir traiter automatiquement les factures électroniques reçues et envoyer des factures électroniques, avec un rapport d''avancement trimestriel à l''autorité Peppol australienne.', '["Vérifiez que votre dispositif de facturation électronique prend en charge un traitement entièrement automatisé et sans intervention manuelle", "Les fournisseurs du gouvernement devraient s''attendre à des cycles de paiement plus rapides à mesure que l''automatisation se met en place"]');
